import java.io.*;
import java.util.*;

public class Main {
    static ArrayList<Long> nums = new ArrayList<>();

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());

        generateNumbers();
        Collections.sort(nums);

        int left = lowerBound(nums, a);
        int right = upperBound(nums, b);
        System.out.println(right - left);
    }

    // Generate all numbers with exactly one zero in binary representation
    private static void generateNumbers() {
        // Maximum bits needed for numbers up to 1e18 is about 60
        for (int n = 2; n <= 60; n++) {
            long fullOnes = (n == 64) ? -1L : ((1L << n) - 1); // (2^n - 1)
            for (int i = 0; i < n; i++) {
                long num = fullOnes ^ (1L << i); // flip bit i from 1 to 0
                if (num > 0) {
                    nums.add(num);
                }
            }
        }
    }

    private static int lowerBound(List<Long> list, long target) {
        int l = 0, r = list.size();
        while (l < r) {
            int m = (l + r) >>> 1;
            if (list.get(m) < target) l = m + 1;
            else r = m;
        }
        return l;
    }

    private static int upperBound(List<Long> list, long target) {
        int l = 0, r = list.size();
        while (l < r) {
            int m = (l + r) >>> 1;
            if (list.get(m) <= target) l = m + 1;
            else r = m;
        }
        return l;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    // Count numbers <= x that have exactly one zero in binary representation
    private static long count(long x) {
        if (x <= 0) return 0;
        long res = 0;

        // For length L (number of bits) from 2 upwards
        for (int L = 2; ; L++) {
            long maxForLen = (1L << L) - 1; // largest L-bit number (all ones)
            if (maxForLen > x && L > 62) break; // safety for very large L

            // For each position of the single zero (from 0 to L-1)
            for (int z = 0; z < L; z++) {
                long num = ((1L << L) - 1) ^ (1L << z); // all ones except one zero
                if (num > x) continue;
                res++;
            }

            if (maxForLen > x) break;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());

        long ans = count(b) - count(a - 1);
        System.out.println(ans);
    }
}

