public class Main {
    // Count numbers in [1, x] having exactly one zero in binary representation
    private static long countUpTo(long x) {
        if (x <= 0) return 0;
        long count = 0;
        // For each bit length L (number of bits)
        for (int L = 2; ; L++) {
            long maxForLength = (1L << L) - 1; // largest number with L bits (all ones)
            if (maxForLength > x && L > 60) break; // safety break for very large L

            // For each position of zero (0-based from least significant bit)
            for (int z = 0; z < L; z++) {
                long n = maxForLength - (1L << z); // all ones except bit z is zero
                if (n > x) continue;
                if (n >= 1) count++;
            }
            // If even the smallest number with this length (all ones except highest bit zero)
            // is greater than x, further lengths will only produce larger numbers.
            if (maxForLength > x && L > 60) break;
        }
        return count;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());

        long result = countUpTo(b) - countUpTo(a - 1);
        System.out.println(result);
    }
}

