import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long a = fs.nextLong();
        long b = fs.nextLong();

        long count = 0;
        // Maximum bits needed for numbers up to 1e18 is about 60
        for (int len = 2; len <= 60; len++) {
            // position of zero bit (0-based from LSB), can't be MSB or LSB
            for (int zeroPos = 1; zeroPos < len - 1; zeroPos++) {
                long num = ((1L << len) - 1) ^ (1L << zeroPos);
                if (num < a) continue;
                if (num > b) continue;
                count++;
            }
        }

        System.out.println(count);
    }

    // Simple fast scanner
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    // Count numbers <= x with exactly one zero in binary representation
    private static long count(long x) {
        if (x <= 0) return 0;
        long res = 0;
        // length of binary representation (number of bits)
        int maxBits = 0;
        long tmp = x;
        while (tmp > 0) {
            maxBits++;
            tmp >>= 1;
        }
        // For each possible bit length
        for (int n = 2; n <= maxBits; n++) {
            // For each position of the single zero (0 = MSB, n-1 = LSB)
            for (int z = 0; z < n; z++) {
                // Skip leading zero (no leading zeros allowed)
                if (z == 0) continue;
                long num = 0;
                for (int i = 0; i < n; i++) {
                    int bit = (i == z) ? 0 : 1;
                    num = (num << 1) | bit;
                }
                if (num <= x) res++;
            }
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long a = fs.nextLong();
        long b = fs.nextLong();
        long ans = count(b) - count(a - 1);
        System.out.println(ans);
    }

    // Simple fast scanner
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

