import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    // Count numbers in [1, x] whose binary representation has exactly one '0'
    private static long countUpTo(long x) {
        if (x <= 0) return 0;
        long count = 0;

        // For each possible bit length L (number of bits)
        for (int L = 2; ; L++) {
            // Maximum number with L bits is (1<<L) - 1
            // If that is greater than x, we may still have some numbers of this length <= x
            // but if the smallest number with L bits (1<<(L-1)) is > x, we can break.
            if ((1L << (L - 1)) > x) break;

            // For each position of the single zero (0-based from LSB)
            for (int i = 0; i < L; i++) {
                // Construct number: all ones except bit i is zero
                long n = ((1L << L) - 1) ^ (1L << i);
                if (n > x) continue;
                // Ensure it has exactly L bits (no leading zero)
                if ((n & (1L << (L - 1))) == 0) continue;
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long a = fs.nextLong();
        long b = fs.nextLong();

        long result = countUpTo(b) - countUpTo(a - 1);
        System.out.println(result);
    }

    // Simple fast scanner
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
