import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    // Count numbers in [1, x] with exactly one zero in binary representation
    private static long count(long x) {
        if (x <= 0) return 0;
        long res = 0;
        // For each bit length L (number of bits)
        for (int L = 2; ; L++) {
            // Maximum number with L bits is (1<<L) - 1
            if ((1L << L) - 1 > x && L > 60) break; // safety for large L
            // For each position of zero (0-based from LSB)
            for (int z = 0; z < L; z++) {
                long n = (1L << L) - 1 - (1L << z);
                if (n > x) continue;
                if (n > 0) res++;
            }
            // Stop when minimal L-bit number exceeds x
            if ((1L << (L - 1)) > x) break;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long ans = count(b) - count(a - 1);
        System.out.println(ans);
    }
}
